/* ---------- SMALLTALK & HÖFLICHKEIT · 🟨 A2·B1 (aus alter Landeskunde-App übernommen + ergänzt) ---------- */
stufe('smalltalk','ab',{"titel": "Smalltalk & Höflichkeit", "emoji": "💬", "bereich": "Landeskunde DACH", "intro": "Worüber redet man mit Fremden – und worüber lieber nicht?", "glossar": {"Floskel": {"e": "🗨️", "t": "ein Satz, den man aus Höflichkeit sagt. Man meint ihn nicht ganz wörtlich."}, "Smalltalk": {"e": "☕", "t": "ein kurzes, lockeres Gespräch über einfache Themen."}}, "dach": ["Typische <g>Smalltalk</g>-Themen: Wetter, Wochenende, Urlaub, Essen – nicht Gehalt, Alter oder Politik.", "Beim Ankommen sagt man „Hallo / Guten Tag“, beim Gehen „Tschüss / Auf Wiedersehen“, auch im Laden.", "„Wie geht’s?“ ist oft nur höfliche <g>Floskel</g> – eine kurze Antwort reicht.", "Man hält etwas Abstand und schaut beim Sprechen in die Augen."], "skala": {"titel": "💬 Welches Thema passt?", "legende": "🔴 lieber nicht &nbsp; 🟡 nur mit Freunden &nbsp; 🟢 immer gut. Und wie ist das in eurem Land?"}, "situationen": [{"o": "Gehalt & Geld", "ic": "💶", "s": 3, "meter": 92, "w": "lieber nicht", "t": "Über Geld spricht man mit Fremden fast nie."}, {"o": "Familie & Liebe", "ic": "❤️", "s": 2, "meter": 55, "w": "mit Freunden", "t": "Erst wenn man sich besser kennt."}, {"o": "Wetter & Wochenende", "ic": "🌤️", "s": 1, "meter": 12, "w": "immer gut", "t": "Das passt immer – beim Bäcker, im Büro, im Bus."}], "merk": "Beim Smalltalk: Wetter, Wochenende, Urlaub – ja. Geld, Alter, Politik – lieber nicht.", "fragen": [{"q": "Und, was hast du am Wochenende gemacht?", "folge": ["Mit wem warst du unterwegs?", "Was machst du nächstes Wochenende?"], "antw": ["Ich habe mich mit Freunden getroffen.", "Nicht viel – ich habe mich ausgeruht.", "Ich war einkaufen und spazieren."]}, {"q": "Worüber macht man in deinem Land Smalltalk?", "folge": ["Welche Themen sind bei euch tabu?", "Fällt dir Smalltalk auf Deutsch leicht?"], "antw": ["Bei uns redet man oft über Essen und Familie.", "Über Geld spricht man bei uns nicht.", "Smalltalk auf Deutsch finde ich noch schwer."]}, {"q": "Wie begrüßt man sich in deiner Kultur?", "folge": ["Gibt man sich die Hand oder umarmt man sich?", "Was sagt man beim Abschied?"], "antw": ["Bei uns umarmt man sich zur Begrüßung.", "Wir geben uns die Hand.", "Zum Abschied sagt man bei uns …"]}], "chunks": [{"h": "Smalltalk beginnen", "l": ["Schönes Wetter heute, oder?", "Und, wie war dein Tag?", "Warst du schon mal in …?"]}, {"h": "Höflich reagieren", "l": ["Ach, interessant!", "Das klingt schön.", "Oh, das tut mir leid."]}], "vokabeln": [{"w": "der Smalltalk", "bsp": "An der Bushaltestelle machen wir oft Smalltalk.", "ue": "kurzes, lockeres Gespräch"}, {"w": "die Floskel", "bsp": "„Wie geht’s?“ ist oft nur eine Floskel.", "ue": "höflicher Satz ohne tiefe Bedeutung"}, {"w": "höflich", "bsp": "Er ist immer sehr höflich.", "ue": "freundlich und respektvoll"}, {"w": "begrüßen", "bsp": "Man begrüßt auch die Verkäuferin.", "ue": "Hallo sagen; willkommen heißen"}], "tipp": "In kleinen Läden oder beim Bäcker ruhig „Hallo“ und „Tschüss“ sagen – das gehört dazu und wirkt freundlich.", "mission": {"t": "Benutzt 5 neue Wörter", "d": "Jedes neue Wort aus dieser Stunde zählt. Schafft ihr 5?", "pts": 20}, "aktiv": {"titel": "Spielt eine kleine Szene", "emoji": "🎭", "aufgabe": "Ihr steht zusammen an der Bushaltestelle. Der Bus kommt zu spät.", "rollenA": "🙋 Beginne ein kurzes Gespräch übers Wetter oder den Bus.", "rollenB": "🚌 Antworte freundlich und stell eine Frage zurück.", "hilfe": ["Der Bus ist heute wieder spät, oder?", "Ja, und es ist so kalt heute!", "Fahren Sie auch in die Stadt?", "Schönen Tag noch!"], "pts": 15}, "quiz": [{"q": "Welches Thema passt gut für Smalltalk?", "o": ["das Wetter", "das Gehalt", "die Politik"], "r": 0}, {"q": "„Wie geht’s?“ – was ist eine gute Antwort?", "o": ["eine lange Geschichte", "„Gut, danke! Und dir?“", "gar nichts sagen"], "r": 1}, {"q": "Was sagt man beim Bäcker, wenn man geht?", "o": ["„Tschüss!“", "„Guten Appetit!“", "„Prost!“"], "r": 0}]});

/* ---------- NACHBARSCHAFT · 🟦 B1·B2 (aus alter Landeskunde-App übernommen + ergänzt) ---------- */
stufe('nachbarn','bb',{"titel": "Nachbarschaft", "emoji": "🏡", "bereich": "Landeskunde DACH", "intro": "Ruhezeit, Putzplan, Grillgeruch – wie lebt man gut mit den Nachbarn?", "glossar": {"Ruhezeit": {"e": "🤫", "t": "Zeit, in der man leise sein muss – meistens nachts und sonntags."}, "Putzplan": {"e": "🧹", "t": "eine Liste: Wer putzt wann das Treppenhaus?"}}, "dach": ["Zwischen 22 und 6 Uhr und oft sonntags gilt die „<g>Ruhezeit</g>“ – keine laute Musik, kein Bohren.", "Beim Einzug stellt man sich den Nachbarn kurz vor; viele Häuser haben einen <g>Putzplan</g> fürs Treppenhaus.", "Mülltrennung, Fahrräder im Flur und Grillgeruch sind klassische Streitthemen.", "Man grüßt sich im Haus, bleibt aber meist eher distanziert-freundlich."], "skala": {"titel": "🏡 Was sorgt für Ärger?", "legende": "🔴 viel Ärger &nbsp; 🟡 manchmal &nbsp; 🟢 kein Problem. Und wie ist das in eurem Land?"}, "situationen": [{"o": "Bohren am Sonntag", "ic": "🔨", "s": 3, "meter": 95, "w": "viel Ärger", "t": "Am Sonntag gilt Ruhe – Bohren ist tabu."}, {"o": "Party am Samstag", "ic": "🎶", "s": 2, "meter": 60, "w": "manchmal", "t": "Vorher Bescheid sagen hilft – ab 22 Uhr leiser."}, {"o": "Im Haus grüßen", "ic": "👋", "s": 1, "meter": 10, "w": "kein Problem", "t": "Ein „Hallo“ im Treppenhaus ist immer gut."}], "merk": "Ab 22 Uhr und sonntags ist Ruhezeit. Wer vorher Bescheid sagt, hat selten Ärger.", "fragen": [{"q": "Wie gut kennst du deine Nachbarn hier?", "folge": ["Grüßt ihr euch im Haus?", "Habt ihr euch schon mal geholfen?"], "antw": ["Ich kenne sie nur vom Sehen.", "Wir grüßen uns, mehr nicht.", "Ein Nachbar hilft mir manchmal."]}, {"q": "Wie ist das Verhältnis zu Nachbarn in deinem Land?", "folge": ["Besucht man sich gegenseitig?", "Ist das in der Stadt anders als auf dem Land?"], "antw": ["Bei uns kennt man die Nachbarn sehr gut.", "Man besucht sich oft spontan.", "In der Stadt ist es anonymer."]}, {"q": "Was würde dich an deutschen Nachbarn überraschen oder stören?", "folge": ["Wie findest du die Ruhezeiten?", "Hattest du schon mal Ärger wegen Lärm?"], "antw": ["Die Ruhezeiten finde ich streng, aber okay.", "Mich stört, dass alle so distanziert sind.", "Ich finde die Ordnung eigentlich angenehm."]}], "chunks": [{"h": "Höflich ansprechen", "l": ["Entschuldigung, könnten Sie bitte etwas leiser sein?", "Ich wollte mich kurz vorstellen – ich bin neu hier.", "Dürfte ich Sie um einen Gefallen bitten?"]}, {"h": "Nachfragen (in der Gruppe)", "l": ["Und wie war das bei dir?", "Kannst du ein Beispiel geben?", "Warum war das so?"]}], "vokabeln": [{"w": "die Ruhezeit", "bsp": "Nach 22 Uhr ist Ruhezeit.", "ue": "Zeit, in der man leise sein muss"}, {"w": "das Treppenhaus", "bsp": "Wir putzen das Treppenhaus abwechselnd.", "ue": "Flur und Treppen im Haus"}, {"w": "sich beschweren", "bsp": "Der Nachbar hat sich über den Lärm beschwert.", "ue": "sagen, dass einen etwas stört"}, {"w": "der Gefallen", "bsp": "Kannst du mir einen Gefallen tun?", "ue": "eine freundliche Hilfe"}], "tipp": "Bohren oder Waschmaschine lieber nicht sonntags oder spät abends – das sorgt am schnellsten für Ärger im Haus.", "mission": {"t": "Benutzt 5 neue Wörter", "d": "Jedes neue Wort aus dieser Stunde zählt. Schafft ihr 5?", "pts": 20}, "aktiv": {"titel": "Spielt eine kleine Szene", "emoji": "🎭", "aufgabe": "Es ist 23 Uhr. Aus der Nachbarwohnung kommt laute Musik.", "rollenA": "😴 Du willst schlafen. Klingel und bitte höflich um Ruhe.", "rollenB": "🎶 Du feierst Geburtstag. Entschuldige dich und finde eine Lösung.", "hilfe": ["Entschuldigung, könnten Sie die Musik etwas leiser machen?", "Oh, das tut mir leid! Ich habe Geburtstag.", "Ich muss morgen früh arbeiten.", "Kein Problem, wir machen jetzt leiser."], "pts": 15}, "quiz": [{"q": "Ab wann ist meistens Ruhezeit?", "o": ["ab 18 Uhr", "ab 22 Uhr", "ab 2 Uhr"], "r": 1}, {"q": "Was macht man sonntags besser nicht?", "o": ["spazieren gehen", "bohren", "lesen"], "r": 1}, {"q": "Was ist ein Putzplan?", "o": ["eine Liste, wer wann putzt", "ein Plan für den Urlaub", "ein Kochrezept"], "r": 0}]});

/* ---------- WOHNEN & MIETE · 🟦 B1·B2 (aus alter Landeskunde-App übernommen + ergänzt) ---------- */
stufe('mieten','bb',{"titel": "Wohnen & Miete", "emoji": "🔑", "bereich": "Landeskunde DACH", "intro": "Kaltmiete, Kaution, keine Küche? Wohnungssuche in DACH ist ein Abenteuer.", "glossar": {"Nebenkosten": {"e": "🧾", "t": "Extra-Kosten zur Miete: Heizung, Wasser, Müll."}, "Kaution": {"e": "🔐", "t": "Geld, das man beim Einzug als Sicherheit zahlt. Beim Auszug bekommt man es zurück."}, "Schufa": {"e": "📊", "t": "eine Firma, die prüft, ob jemand seine Rechnungen zahlt."}}, "dach": ["In Städten ist Wohnraum knapp und teuer. Für eine Wohnung braucht man oft eine <g>Schufa</g>-Auskunft und Gehaltsnachweise.", "Zur Kaltmiete kommen <g>Nebenkosten</g> („warm“). Dazu kommt eine <g>Kaution</g> von bis zu drei Kaltmieten.", "Viele Wohnungen werden ohne Küche vermietet – man bringt sie selbst mit oder kauft sie.", "Mieter haben starke Rechte: Kündigen darf der Vermieter nur mit Frist und gutem Grund."], "skala": {"titel": "🔑 Wie schwer ist die Suche?", "legende": "🔴 sehr schwer &nbsp; 🟡 geht so &nbsp; 🟢 eher leicht. Und wie ist das in eurem Land?"}, "situationen": [{"o": "Großstadt", "ic": "🏙️", "s": 3, "meter": 90, "w": "sehr schwer", "t": "Viele Bewerber für eine Wohnung – oft wochenlange Suche."}, {"o": "WG-Zimmer", "ic": "🛏️", "s": 2, "meter": 55, "w": "geht so", "t": "Schneller zu finden, aber man muss beim WG-Casting gefallen."}, {"o": "Auf dem Land", "ic": "🌳", "s": 1, "meter": 20, "w": "eher leicht", "t": "Mehr Platz, günstigere Miete – aber man braucht oft ein Auto."}], "merk": "Warmmiete = Kaltmiete + Nebenkosten. Die Kaution bekommt man beim Auszug zurück.", "fragen": [{"q": "Wie wohnst du gerade – allein, in einer WG, mit Familie?", "folge": ["Bist du zufrieden damit?", "Was würdest du gern ändern?"], "antw": ["Ich wohne allein in einer kleinen Wohnung.", "Ich wohne in einer WG mit zwei Leuten.", "Ich wohne mit meiner Familie zusammen."]}, {"q": "Was war bei der Wohnungssuche hier schwierig?", "folge": ["Wie lange hast du gesucht?", "Welche Unterlagen brauchtest du?"], "antw": ["Es gab sehr viele Bewerber pro Wohnung.", "Ich habe monatelang gesucht.", "Man braucht Gehaltsnachweis und Schufa."]}, {"q": "Wohnen die Menschen in deinem Land eher zur Miete oder im Eigentum?", "folge": ["Wie teuer ist Wohnen bei euch?", "Wohnt man eher groß oder klein?"], "antw": ["Bei uns kaufen die meisten ein Haus.", "Viele wohnen zur Miete wie hier.", "Wohnen ist bei uns günstiger / teurer."]}], "chunks": [{"h": "Wohnung beschreiben", "l": ["Die Wohnung hat … Zimmer und ist … m² groß.", "Sie ist hell / ruhig / zentral gelegen.", "Die Miete beträgt … Euro warm."]}, {"h": "Bei der Suche", "l": ["Ich suche eine Wohnung mit …", "Ist die Wohnung noch frei?", "Wie hoch ist die Kaution?"]}], "vokabeln": [{"w": "die Kaltmiete", "bsp": "Die Kaltmiete ist ohne Heizung und Wasser.", "ue": "Miete ohne Nebenkosten"}, {"w": "die Nebenkosten", "bsp": "Die Nebenkosten sind dieses Jahr gestiegen.", "ue": "Kosten für Heizung, Wasser, Müll"}, {"w": "die Kaution", "bsp": "Die Kaution beträgt drei Monatsmieten.", "ue": "Sicherheit, die man beim Einzug zahlt"}, {"w": "die WG", "bsp": "Ich wohne in einer WG mit zwei Leuten.", "ue": "Wohngemeinschaft; mehrere teilen eine Wohnung"}], "tipp": "Bei der Besichtigung freundlich auftreten und Unterlagen (Gehaltsnachweis, Schufa) dabeihaben – oft entscheidet der erste Eindruck.", "mission": {"t": "Benutzt 5 neue Wörter", "d": "Jedes neue Wort aus dieser Stunde zählt. Schafft ihr 5?", "pts": 20}, "aktiv": {"titel": "Spielt eine kleine Szene", "emoji": "🎭", "aufgabe": "Besichtigung: Eine Person sucht eine Wohnung, die andere ist der Vermieter.", "rollenA": "🔍 Du suchst eine Wohnung. Stell mindestens drei Fragen.", "rollenB": "🔑 Du bist der Vermieter. Beantworte die Fragen und frag nach Unterlagen.", "hilfe": ["Wie hoch ist die Warmmiete?", "Ist eine Küche dabei?", "Haben Sie eine Schufa-Auskunft dabei?", "Ab wann ist die Wohnung frei?"], "pts": 15}, "quiz": [{"q": "Was ist die Warmmiete?", "o": ["Kaltmiete + Nebenkosten", "nur die Heizung", "die Kaution"], "r": 0}, {"q": "Was bekommt man beim Auszug zurück?", "o": ["die Nebenkosten", "die Kaution", "die Küche"], "r": 1}, {"q": "Was fehlt in vielen deutschen Mietwohnungen?", "o": ["das Bad", "die Küche", "die Fenster"], "r": 1}]});

/* ---------- ANMELDEN & ÄMTER · 🟦 B1·B2 (aus alter Landeskunde-App übernommen + ergänzt) ---------- */
stufe('aemter','bb',{"titel": "Anmelden & Ämter", "emoji": "🏛️", "bereich": "Landeskunde DACH", "intro": "Termin, Formular, Stempel – so überlebst du das deutsche Amt.", "glossar": {"Bürgeramt": {"e": "🏛️", "t": "das Amt in der Stadt, bei dem man sich anmeldet."}, "Wohnungsgeberbestätigung": {"e": "📝", "t": "ein Zettel vom Vermieter: Diese Person wohnt hier."}, "Bürokratie": {"e": "📚", "t": "viele Regeln, Formulare und Papiere bei Ämtern."}}, "dach": ["Nach dem Umzug muss man sich innerhalb von 14 Tagen beim <g>Bürgeramt</g> anmelden.", "Für viele Ämter braucht man einen Online-Termin – spontan vorbeigehen klappt selten.", "Die deutsche <g>Bürokratie</g> liebt Papier: Formulare, Unterschriften, Nachweise.", "Für die Anmeldung braucht man den Pass und eine <g>Wohnungsgeberbestätigung</g> vom Vermieter."], "skala": {"titel": "🏛️ Wie viel Papier?", "legende": "🔴 sehr viel &nbsp; 🟡 mittel &nbsp; 🟢 wenig. Und wie ist das in eurem Land?"}, "situationen": [{"o": "Aufenthalt & Visum", "ic": "🛂", "s": 3, "meter": 95, "w": "sehr viel", "t": "Viele Dokumente, lange Wartezeit – früh anfangen!"}, {"o": "Anmeldung", "ic": "✍️", "s": 2, "meter": 55, "w": "mittel", "t": "Pass + Bestätigung vom Vermieter, dann geht es schnell."}, {"o": "Bibliotheksausweis", "ic": "📚", "s": 1, "meter": 15, "w": "wenig", "t": "Ausweis zeigen, fertig."}], "merk": "Anmelden innerhalb von 14 Tagen. Termin online buchen und alle Unterlagen mitbringen.", "fragen": [{"q": "Welche Erfahrung hast du schon mit einem deutschen Amt gemacht?", "folge": ["Was war am kompliziertesten?", "Hat dir jemand geholfen?"], "antw": ["Die Anmeldung war einfacher als gedacht.", "Ich habe ewig auf einen Termin gewartet.", "Ein Freund hat mir beim Formular geholfen."]}, {"q": "Wie läuft Bürokratie in deinem Land ab – auch so viel Papier?", "folge": ["Geht bei euch vieles online?", "Muss man auch Termine machen?"], "antw": ["Bei uns ist fast alles digital.", "Es gibt auch viel Papier wie hier.", "Man kann oft spontan vorbeigehen."]}, {"q": "Was würdest du an den Ämtern ändern?", "folge": ["Sollte mehr online gehen?", "Was hat dich am meisten genervt?"], "antw": ["Ich würde alles digital machen.", "Die Wartezeiten sind zu lang.", "Die Formulare sollten einfacher sein."]}], "chunks": [{"h": "Beim Amt", "l": ["Ich möchte mich anmelden.", "Ich habe einen Termin um … Uhr.", "Welche Unterlagen brauchen Sie?"]}, {"h": "Nachfragen", "l": ["Könnten Sie das bitte wiederholen?", "Was bedeutet dieses Feld?", "Bis wann muss ich das einreichen?"]}], "vokabeln": [{"w": "die Anmeldung", "bsp": "Die Anmeldung mache ich beim Bürgeramt.", "ue": "offiziell mitteilen, wo man wohnt"}, {"w": "das Formular", "bsp": "Bitte füllen Sie das Formular aus.", "ue": "Papier mit Feldern zum Ausfüllen"}, {"w": "der Nachweis", "bsp": "Ich brauche einen Nachweis über mein Einkommen.", "ue": "Dokument, das etwas beweist"}, {"w": "die Frist", "bsp": "Die Frist läuft am Freitag ab.", "ue": "letzter Termin für etwas"}], "tipp": "Termine beim Bürgeramt früh online buchen – beliebte Zeiten sind oft wochenlang ausgebucht.", "mission": {"t": "Benutzt 5 neue Wörter", "d": "Jedes neue Wort aus dieser Stunde zählt. Schafft ihr 5?", "pts": 20}, "aktiv": {"titel": "Spielt eine kleine Szene", "emoji": "🎭", "aufgabe": "Eine Person meldet sich beim Bürgeramt an, die andere arbeitet dort.", "rollenA": "✍️ Du willst dich anmelden. Erkläre, warum du da bist.", "rollenB": "🏛️ Du arbeitest im Amt. Frag nach Unterlagen – eine fehlt!", "hilfe": ["Guten Tag, ich möchte mich anmelden.", "Haben Sie einen Termin?", "Ich brauche noch die Bestätigung vom Vermieter.", "Kann ich das Dokument später nachreichen?"], "pts": 15}, "quiz": [{"q": "Wie lange hat man Zeit für die Anmeldung?", "o": ["14 Tage", "1 Jahr", "3 Monate"], "r": 0}, {"q": "Was braucht man für die Anmeldung?", "o": ["Pass und Bestätigung vom Vermieter", "nur ein Foto", "den Führerschein"], "r": 0}, {"q": "Wie bekommt man meistens einen Termin beim Amt?", "o": ["online buchen", "einfach anrufen um Mitternacht", "gar nicht"], "r": 0}]});

/* ---------- MÜLLTRENNUNG · 🟩 B2·C1 (aus alter Landeskunde-App übernommen + ergänzt) ---------- */
stufe('muell','bc',{"titel": "Mülltrennung", "emoji": "♻️", "bereich": "Landeskunde DACH", "intro": "Fünf Tonnen und ein Pfandautomat: Ist Mülltrennung Ordnung oder schon Obsession?", "glossar": {"Pfand": {"e": "♻️", "t": "Geld auf Flaschen und Dosen. Man bekommt es beim Zurückgeben zurück."}, "Hausverwaltung": {"e": "🏢", "t": "die Firma, die sich um das Haus und die Mieter kümmert."}}, "dach": ["Müll wird getrennt: Papier (blau), Verpackungen (gelb), Bio (braun), Restmüll (grau), Glas nach Farben.", "Auf viele Flaschen und Dosen gibt es <g>Pfand</g> – im Supermarkt am Automaten zurückgeben.", "Falsch getrennter Müll kann Ärger mit Nachbarn oder der <g>Hausverwaltung</g> geben.", "Sonntags und nachts bringt man Glas aus Rücksicht nicht zum Container (Lärm)."], "skala": {"titel": "♻️ Wie streng wird getrennt?", "legende": "🔴 sehr genau &nbsp; 🟡 mittel &nbsp; 🟢 locker. Und wie ist das in eurem Land?"}, "situationen": [{"o": "Mehrfamilienhaus", "ic": "🏢", "s": 3, "meter": 88, "w": "sehr genau", "t": "Falsch getrennt? Dann gibt es schnell einen Zettel im Treppenhaus."}, {"o": "Büro", "ic": "💼", "s": 2, "meter": 55, "w": "mittel", "t": "Papier und Rest werden getrennt, der Rest oft weniger genau."}, {"o": "Festival & Party", "ic": "🎪", "s": 1, "meter": 20, "w": "locker", "t": "Hier landet vieles im selben Sack – Pfandbecher ausgenommen."}], "merk": "Blau = Papier, Gelb = Verpackung, Braun = Bio, Grau = Rest, Glas nach Farben. Pfandflaschen zurück im Supermarkt.", "fragen": [{"q": "Findest du die deutsche Mülltrennung sinnvoll oder übertrieben?", "folge": ["Was war am Anfang verwirrend für dich?", "Trennst du selbst konsequent?"], "antw": ["Ich finde das sehr sinnvoll fürs Klima.", "Ehrlich gesagt ist es mir fast zu viel.", "Am Anfang wusste ich nie, was wohin kommt."]}, {"q": "Wie wird der Müll in deinem Land getrennt?", "folge": ["Gibt es bei euch Pfand?", "Wird Müll bei euch recycelt?"], "antw": ["Bei uns trennt man nicht so streng.", "Es gibt kein Pfand wie hier.", "Wir trennen nur Papier und Rest."]}, {"q": "Was könnte jeder im Alltag für weniger Müll tun?", "folge": ["Kaufst du verpackungsfrei ein?", "Benutzt du Mehrweg statt Einweg?"], "antw": ["Ich nehme immer eigene Taschen mit.", "Man kann auf Plastik verzichten.", "Ich kaufe öfter unverpackt."]}], "chunks": [{"h": "Meinung & Vergleich", "l": ["Ich finde das (sehr) sinnvoll / übertrieben.", "Bei uns trennt man (nicht) so streng.", "Daran musste ich mich erst gewöhnen."]}, {"h": "Erklären", "l": ["Das kommt in die gelbe Tonne / ins Altglas.", "Darauf gibt es Pfand.", "Das gehört in den Restmüll."]}], "vokabeln": [{"w": "die Mülltrennung", "bsp": "Die Mülltrennung ist hier sehr genau.", "ue": "Abfall nach Sorten getrennt sammeln"}, {"w": "das Pfand", "bsp": "Auf die Flasche gibt es 25 Cent Pfand.", "ue": "Geld, das man beim Zurückgeben zurückbekommt"}, {"w": "die Tonne", "bsp": "Die gelbe Tonne ist für Verpackungen.", "ue": "großer Müllbehälter"}, {"w": "der Restmüll", "bsp": "Das gehört in den Restmüll.", "ue": "Abfall, der nicht recycelt wird"}], "tipp": "Pfandflaschen nicht wegwerfen – am Automaten im Supermarkt gibt es das Geld zurück.", "mission": {"t": "Benutzt 5 neue Wörter", "d": "Jedes neue Wort aus dieser Stunde zählt. Schafft ihr 5?", "pts": 20}, "aktiv": {"titel": "Spielt eine kleine Szene", "emoji": "🎭", "aufgabe": "Ein neuer Nachbar wirft Glas in den Restmüll. Jemand aus dem Haus spricht ihn darauf an.", "rollenA": "🏢 Du wohnst schon lange hier. Erkläre die Mülltrennung freundlich, aber bestimmt.", "rollenB": "📦 Du bist neu und findest das System übertrieben. Begründe deine Meinung.", "hilfe": ["Entschuldigung, aber das gehört eigentlich ins Altglas.", "Ehrlich gesagt finde ich das System ziemlich kompliziert.", "Wenn wir falsch trennen, zahlen alle mehr.", "Okay, können Sie mir kurz zeigen, was wohin gehört?"], "pts": 15}, "quiz": [{"q": "In welche Tonne kommt Papier?", "o": ["blau", "gelb", "braun"], "r": 0}, {"q": "Wo gibt man Pfandflaschen zurück?", "o": ["im Supermarkt am Automaten", "bei der Post", "in der gelben Tonne"], "r": 0}, {"q": "Warum bringt man sonntags kein Glas zum Container?", "o": ["wegen des Lärms", "weil es verboten ist zu laufen", "weil Glas sonntags teurer ist"], "r": 0}, {"q": "Was gehört in die gelbe Tonne?", "o": ["Verpackungen", "Essensreste", "Zeitungen"], "r": 0}]});

/* ---------- EINKAUFEN & PFAND · 🟨 A2·B1 (aus alter Landeskunde-App übernommen + ergänzt) ---------- */
stufe('einkaufen','ab',{"titel": "Einkaufen & Pfand", "emoji": "🛒", "bereich": "Landeskunde DACH", "intro": "Schnell einpacken, Tasche mitbringen, sonntags zu – so kauft man hier ein.", "glossar": {"Pfand": {"e": "♻️", "t": "Geld auf Flaschen und Dosen. Man bekommt es beim Zurückgeben zurück."}, "Bargeld": {"e": "💶", "t": "Geld als Münzen und Scheine."}}, "dach": ["An der Kasse muss man schnell einpacken – am besten eine eigene Tasche mitbringen (Tüten kosten extra).", "Oft zahlt man bar oder mit Karte; in kleinen Läden gilt manchmal „nur <g>Bargeld</g>“.", "Sonntags haben die meisten Geschäfte geschlossen – nur Bahnhof, Tankstelle und Bäcker öffnen.", "Auf Flaschen und Dosen gibt es <g>Pfand</g>, das man am Automaten zurückbekommt."], "skala": {"titel": "🛒 Wann ist offen?", "legende": "🔴 meistens zu &nbsp; 🟡 manchmal offen &nbsp; 🟢 offen. Und wie ist das in eurem Land?"}, "situationen": [{"o": "Supermarkt am Sonntag", "ic": "🛒", "s": 3, "meter": 95, "w": "zu", "t": "Sonntags sind fast alle Läden geschlossen."}, {"o": "Bäcker am Sonntag", "ic": "🥐", "s": 2, "meter": 50, "w": "manchmal", "t": "Viele Bäcker haben sonntags morgens offen."}, {"o": "Bahnhof & Tankstelle", "ic": "⛽", "s": 1, "meter": 10, "w": "offen", "t": "Hier kann man auch sonntags einkaufen."}], "merk": "Sonntags ist fast alles zu. Eigene Tasche mitbringen und Pfandflaschen zurückgeben.", "fragen": [{"q": "Wann und wo kaufst du am liebsten ein?", "folge": ["Gehst du lieber allein oder mit jemandem?", "Kaufst du auch online ein?"], "antw": ["Ich kaufe meistens im Supermarkt um die Ecke ein.", "Einmal pro Woche mache ich einen Großeinkauf.", "Online kaufe ich nur selten ein."]}, {"q": "Was ist beim Einkaufen hier anders als in deinem Land?", "folge": ["Zahlst du lieber bar oder mit Karte?", "Was machst du, wenn sonntags alles zu hat?"], "antw": ["Bei uns sind die Läden auch sonntags offen.", "Ich zahle lieber mit Karte.", "Ich kaufe freitags für das Wochenende ein."]}, {"q": "Kennst du das Pfandsystem schon gut?", "folge": ["Wo gibst du die Flaschen zurück?", "Findest du das gut?"], "antw": ["Ja, ich gebe die Flaschen im Supermarkt zurück.", "Am Anfang war das neu für mich.", "Ich finde Pfand eine gute Idee."]}], "chunks": [{"h": "An der Kasse", "l": ["Ich hätte gern eine Tüte, bitte.", "Kann ich mit Karte zahlen?", "Nehmen Sie auch Bargeld?"]}, {"h": "Vergleichen", "l": ["Bei uns sind die Läden auch sonntags offen.", "Das Einkaufen ist hier teurer / günstiger.", "So etwas gibt es bei uns (nicht)."]}], "vokabeln": [{"w": "die Kasse", "bsp": "An der Kasse war eine lange Schlange.", "ue": "Ort, wo man bezahlt"}, {"w": "das Bargeld", "bsp": "Ich zahle lieber mit Bargeld.", "ue": "Geld als Münzen und Scheine"}, {"w": "die Tüte", "bsp": "Eine Tüte kostet 20 Cent.", "ue": "Beutel zum Einpacken"}, {"w": "geschlossen", "bsp": "Sonntags ist der Supermarkt geschlossen.", "ue": "nicht offen, zu"}], "tipp": "Freitags oder samstags für das Wochenende einkaufen – sonntags bleiben die Supermärkte zu.", "mission": {"t": "Benutzt 5 neue Wörter", "d": "Jedes neue Wort aus dieser Stunde zählt. Schafft ihr 5?", "pts": 20}, "aktiv": {"titel": "Spielt eine kleine Szene", "emoji": "🎭", "aufgabe": "Eine Person kassiert im Supermarkt, die andere kauft ein.", "rollenA": "🛒 Du kaufst ein. Frag nach einer Tüte und zahl mit Karte.", "rollenB": "💶 Du sitzt an der Kasse. Sag den Preis und frag nach dem Bon.", "hilfe": ["Das macht 12,50 Euro.", "Kann ich mit Karte zahlen?", "Brauchen Sie eine Tüte?", "Möchten Sie den Bon?"], "pts": 15}, "quiz": [{"q": "Wann sind die meisten Läden geschlossen?", "o": ["am Montag", "am Sonntag", "am Mittwoch"], "r": 1}, {"q": "Was bekommt man am Pfandautomaten?", "o": ["Geld zurück", "eine neue Flasche", "einen Kaffee"], "r": 0}, {"q": "Was bringt man am besten zum Einkaufen mit?", "o": ["eine eigene Tasche", "einen Stuhl", "einen Pass"], "r": 0}]});

/* ---------- FEIERTAGE & FESTE · 🟨 A2·B1 (aus alter Landeskunde-App übernommen + ergänzt) ---------- */
stufe('feste','ab',{"titel": "Feiertage & Feste", "emoji": "🎉", "bereich": "Landeskunde DACH", "intro": "Vom Weihnachtsbaum bis zum Feuerwerk: Wie feiert man in DACH?", "glossar": {"Feiertag": {"e": "📅", "t": "ein besonderer freier Tag. Viele Menschen müssen nicht arbeiten."}, "Bundesland": {"e": "🗺️", "t": "ein Teil von Deutschland, z. B. Bayern oder Berlin."}}, "dach": ["Weihnachten feiert man am 24. Dezember abends mit Familie, Baum und Geschenken.", "Silvester (31.12.) wird laut mit Feuerwerk gefeiert, Ostern eher ruhig mit Eiern und Hasen.", "An einem <g>Feiertag</g> sind die Geschäfte geschlossen. Feste wie Karneval oder Oktoberfest sind sehr beliebt.", "Welche Tage frei sind, ist in jedem <g>Bundesland</g> ein bisschen anders."], "skala": {"titel": "🎉 Laut oder leise?", "legende": "🔴 sehr laut &nbsp; 🟡 gemischt &nbsp; 🟢 ruhig. Und wie ist das in eurem Land?"}, "situationen": [{"o": "Silvester", "ic": "🎆", "s": 3, "meter": 95, "w": "sehr laut", "t": "Feuerwerk, Partys und „Prosit Neujahr!“ um Mitternacht."}, {"o": "Karneval", "ic": "🎭", "s": 2, "meter": 70, "w": "gemischt", "t": "In Köln und Mainz laut und bunt, in anderen Städten ruhig."}, {"o": "Weihnachten", "ic": "🎄", "s": 1, "meter": 15, "w": "ruhig", "t": "Ein ruhiges Fest mit Familie und gutem Essen."}], "merk": "Weihnachten ist am 24. Dezember abends. An Feiertagen sind die Läden zu.", "fragen": [{"q": "Welches Fest feierst du am liebsten – und wie?", "folge": ["Mit wem feierst du?", "Was esst ihr an dem Tag?"], "antw": ["Am liebsten feiere ich … mit der Familie.", "Wir treffen uns alle und kochen zusammen.", "An dem Tag isst man typischerweise …"]}, {"q": "Welche Feste feiert man in deinem Land?", "folge": ["Gibt es ein Fest, das Deutsche nicht kennen?", "Wann ist bei euch das wichtigste Fest?"], "antw": ["Bei uns ist … das wichtigste Fest.", "Wir feiern … im … .", "So ein Fest gibt es in Deutschland nicht."]}, {"q": "Welches deutsche Fest würdest du gern erleben?", "folge": ["Warum gerade das?", "Was weißt du schon darüber?"], "antw": ["Ich würde gern das Oktoberfest erleben.", "Weihnachten auf einem Weihnachtsmarkt klingt schön.", "Über Karneval habe ich viel gehört."]}], "chunks": [{"h": "Über Feste sprechen", "l": ["Bei uns feiert man … im … .", "An dem Tag isst man typischerweise …", "Man trifft sich mit Familie und …"]}, {"h": "Vergleichen", "l": ["Das ist ähnlich wie bei uns.", "So ein Fest kennen wir nicht.", "Am liebsten feiere ich …"]}], "vokabeln": [{"w": "der Feiertag", "bsp": "Am Feiertag haben die Läden zu.", "ue": "besonderer freier Tag"}, {"w": "das Feuerwerk", "bsp": "An Silvester gibt es Feuerwerk.", "ue": "bunte Lichter und Knaller am Himmel"}, {"w": "feiern", "bsp": "Wir feiern Weihnachten mit der Familie.", "ue": "ein Fest begehen, fröhlich sein"}, {"w": "das Geschenk", "bsp": "Unter dem Baum liegen Geschenke.", "ue": "etwas, das man jemandem schenkt"}], "tipp": "Achte auf die Feiertage deines Bundeslandes – an manchen Tagen ist frei, an anderen nicht.", "mission": {"t": "Benutzt 5 neue Wörter", "d": "Jedes neue Wort aus dieser Stunde zählt. Schafft ihr 5?", "pts": 20}, "aktiv": {"titel": "Spielt eine kleine Szene", "emoji": "🎭", "aufgabe": "Eine Person lädt die andere zu einem Fest aus ihrem Land ein.", "rollenA": "🎉 Lade ein und erkläre: Was macht man an dem Tag?", "rollenB": "🙋 Du bist eingeladen. Stell Fragen und sag zu.", "hilfe": ["Möchtest du nächste Woche mit uns feiern?", "Was macht man an dem Tag?", "Soll ich etwas mitbringen?", "Sehr gern, ich komme!"], "pts": 15}, "quiz": [{"q": "Wann feiert man in Deutschland Weihnachten mit Geschenken?", "o": ["am 24. Dezember abends", "am 1. Januar", "am 31. Oktober"], "r": 0}, {"q": "Was gibt es an Silvester?", "o": ["Feuerwerk", "Ostereier", "Laternen"], "r": 0}, {"q": "Was ist an einem Feiertag meistens geschlossen?", "o": ["die Geschäfte", "die Krankenhäuser", "die Polizei"], "r": 0}]});

/* ---------- VEREINE · 🟦 B1·B2 (aus alter Landeskunde-App übernommen + ergänzt) ---------- */
stufe('verein','bb',{"titel": "Vereine", "emoji": "⚽", "bereich": "Landeskunde DACH", "intro": "Fußball, Chor oder Schrebergarten: Warum gibt es so viele Vereine?", "glossar": {"Ehrenamt": {"e": "🙌", "t": "freiwillige Arbeit, für die man kein Geld bekommt."}, "Mitgliedsbeitrag": {"e": "💳", "t": "Geld, das Mitglieder regelmäßig an den Verein zahlen."}, "Schrebergarten": {"e": "🌻", "t": "ein kleiner Garten in einer Gartensiedlung, oft am Stadtrand."}}, "dach": ["Deutschland ist ein „Land der Vereine“ – vom Sport- bis zum <g>Schrebergarten</g>- oder Karnevalsverein.", "Im Verein findet man leicht Kontakt, Freunde und ein Hobby – oft günstig.", "Viele Vereine leben vom <g>Ehrenamt</g>: Menschen helfen freiwillig und unbezahlt.", "Ein Verein hat meist eine Satzung, einen Vorstand und einen <g>Mitgliedsbeitrag</g>."], "skala": {"titel": "⚽ Wie leicht kommt man rein?", "legende": "🔴 schwer &nbsp; 🟡 mit etwas Geduld &nbsp; 🟢 ganz leicht. Und wie ist das in eurem Land?"}, "situationen": [{"o": "Schrebergarten", "ic": "🌻", "s": 3, "meter": 85, "w": "schwer", "t": "Oft lange Wartelisten und viele Regeln."}, {"o": "Chor & Musik", "ic": "🎵", "s": 2, "meter": 50, "w": "mit Geduld", "t": "Man fragt, kommt zur Probe – und bleibt."}, {"o": "Sportverein", "ic": "⚽", "s": 1, "meter": 15, "w": "ganz leicht", "t": "Probetraining, Beitrag zahlen, fertig."}], "merk": "Im Verein findet man schnell Kontakt und übt Deutsch im Alltag. Viele Vereine leben vom Ehrenamt.", "fragen": [{"q": "Bist du in einem Verein oder Club? In welchem?", "folge": ["Wie oft trefft ihr euch?", "Wie hast du die Leute kennengelernt?"], "antw": ["Ja, ich bin in einem Sportverein.", "Nein, aber ich würde gern eintreten.", "Früher war ich in einem … -Verein."]}, {"q": "Gibt es so etwas wie deutsche Vereine in deinem Land?", "folge": ["Wie organisiert man dort Hobbys?", "Engagiert man sich bei euch ehrenamtlich?"], "antw": ["Bei uns gibt es eher lose Gruppen.", "So feste Vereine kennen wir nicht.", "Ehrenamt ist bei uns auch verbreitet."]}, {"q": "In welchen Verein würdest du hier gern eintreten?", "folge": ["Warum gerade dieser?", "Was erhoffst du dir davon?"], "antw": ["Ich würde gern in einen Sportverein eintreten.", "Ein Musikverein würde mir gefallen.", "Ich suche vor allem Kontakt zu Leuten."]}], "chunks": [{"h": "Über Vereine sprechen", "l": ["Ich bin in einem … -Verein.", "Ich würde gern in einen … -Verein eintreten.", "Dort trifft man sich einmal pro Woche."]}, {"h": "Begründen", "l": ["Ich interessiere mich für …", "Das wäre gut, weil …", "So lerne ich neue Leute kennen."]}], "vokabeln": [{"w": "der Verein", "bsp": "Mein Sohn ist im Fußballverein.", "ue": "Gruppe mit gemeinsamem Hobby oder Ziel"}, {"w": "das Ehrenamt", "bsp": "Sie arbeitet im Ehrenamt bei der Tafel.", "ue": "freiwillige, unbezahlte Arbeit"}, {"w": "eintreten", "bsp": "Ich bin in den Chor eingetreten.", "ue": "Mitglied werden"}, {"w": "der Beitrag", "bsp": "Der Beitrag kostet zehn Euro im Monat.", "ue": "Geld, das Mitglieder regelmäßig zahlen"}], "tipp": "Ein Verein ist einer der einfachsten Wege, schnell Leute kennenzulernen und Deutsch im Alltag zu sprechen.", "mission": {"t": "Benutzt 5 neue Wörter", "d": "Jedes neue Wort aus dieser Stunde zählt. Schafft ihr 5?", "pts": 20}, "aktiv": {"titel": "Spielt eine kleine Szene", "emoji": "🎭", "aufgabe": "Eine Person ruft bei einem Verein an und möchte mitmachen.", "rollenA": "📞 Du interessierst dich für den Verein. Frag nach Zeiten und Kosten.", "rollenB": "⚽ Du bist im Vorstand. Erkläre alles und lade zum Probetraining ein.", "hilfe": ["Ich interessiere mich für Ihren Verein.", "Wann und wo trefft ihr euch?", "Wie hoch ist der Mitgliedsbeitrag?", "Komm doch einfach am Dienstag vorbei!"], "pts": 15}, "quiz": [{"q": "Was ist ein Ehrenamt?", "o": ["freiwillige Arbeit ohne Geld", "ein Job im Rathaus", "ein Preis"], "r": 0}, {"q": "Was zahlen Mitglieder regelmäßig?", "o": ["einen Mitgliedsbeitrag", "eine Kaution", "Pfand"], "r": 0}, {"q": "Warum ist ein Verein gut für Deutschlerner?", "o": ["Man spricht im Alltag Deutsch.", "Man muss nie sprechen.", "Man lernt nur Englisch."], "r": 0}]});

/* ---------- ESSEN & ESSKULTUR · 🟨 A2·B1 (aus alter Landeskunde-App übernommen + ergänzt) ---------- */
stufe('esskultur','ab',{"titel": "Essen & Esskultur", "emoji": "🍽️", "bereich": "Landeskunde DACH", "intro": "Abendbrot, Kaffee und Kuchen, „Guten Appetit“ – was kommt auf den Tisch?", "glossar": {"Abendbrot": {"e": "🍞", "t": "ein kaltes Abendessen mit Brot, Käse und Wurst."}, "Kaffee und Kuchen": {"e": "🍰", "t": "eine kleine Pause am Nachmittag, oft am Sonntag."}}, "dach": ["Das warme Hauptessen war traditionell mittags; heute essen viele abends warm.", "Abends gibt es oft „<g>Abendbrot</g>“: Brot mit Käse, Wurst und Gemüse.", "Man wünscht „Guten Appetit“ und wartet oft, bis alle am Tisch sind.", "Brot, Bier, Wurst und „<g>Kaffee und Kuchen</g>“ am Nachmittag sind sehr beliebt."], "skala": {"titel": "🍽️ Wann isst man warm?", "legende": "🔴 fast immer &nbsp; 🟡 manchmal &nbsp; 🟢 eher kalt. Und wie ist das in eurem Land?"}, "situationen": [{"o": "Mittag in der Kantine", "ic": "🍲", "s": 3, "meter": 85, "w": "warm", "t": "Mittags gibt es oft ein warmes Essen."}, {"o": "Sonntag in der Familie", "ic": "👨‍👩‍👧", "s": 2, "meter": 55, "w": "manchmal", "t": "Großes Mittagessen – und nachmittags Kuchen."}, {"o": "Abendbrot zu Hause", "ic": "🍞", "s": 1, "meter": 20, "w": "eher kalt", "t": "Brot, Käse, Wurst und Gemüse."}], "merk": "Vor dem Essen sagt man „Guten Appetit!“. Abends gibt es oft Abendbrot.", "fragen": [{"q": "Was isst man bei euch typischerweise – und wann?", "folge": ["Wann ist bei euch die Hauptmahlzeit?", "Esst ihr zusammen oder jeder für sich?"], "antw": ["Bei uns isst man mittags warm.", "Das Hauptessen ist bei uns am Abend.", "Wir essen immer zusammen als Familie."]}, {"q": "Was schmeckt dir an der deutschen Küche – und was nicht?", "folge": ["Hast du schon typisch Deutsches probiert?", "Was möchtest du noch probieren?"], "antw": ["Brot und Kuchen schmecken mir sehr.", "Manches ist mir zu deftig.", "Ich möchte noch … probieren."]}, {"q": "Was vermisst du am Essen aus deiner Heimat?", "folge": ["Kochst du das hier selbst?", "Bekommt man die Zutaten hier?"], "antw": ["Ich vermisse das Essen meiner Mutter.", "Ich koche es manchmal selbst.", "Die Zutaten findet man hier leider schwer."]}], "chunks": [{"h": "Über Essen sprechen", "l": ["Bei uns isst man oft …", "Das schmeckt mir (nicht).", "Mein Lieblingsgericht ist …"]}, {"h": "Am Tisch", "l": ["Guten Appetit!", "Könntest du mir bitte das … geben?", "Das ist sehr lecker!"]}], "vokabeln": [{"w": "das Abendbrot", "bsp": "Zum Abendbrot gibt es Brot mit Käse.", "ue": "kaltes Abendessen mit Brot"}, {"w": "das Gericht", "bsp": "Mein Lieblingsgericht ist Lasagne.", "ue": "zubereitetes Essen / Speise"}, {"w": "schmecken", "bsp": "Der Kuchen schmeckt mir sehr.", "ue": "einen (guten) Geschmack haben"}, {"w": "die Mahlzeit", "bsp": "Wir essen drei Mahlzeiten am Tag.", "ue": "Essen zu einer bestimmten Zeit"}], "tipp": "„Kaffee und Kuchen“ am Nachmittag ist eine schöne Gelegenheit, mit Deutschen ins Gespräch zu kommen.", "mission": {"t": "Benutzt 5 neue Wörter", "d": "Jedes neue Wort aus dieser Stunde zählt. Schafft ihr 5?", "pts": 20}, "aktiv": {"titel": "Spielt eine kleine Szene", "emoji": "🎭", "aufgabe": "Ihr sitzt zusammen beim Essen bei einer deutschen Familie.", "rollenA": "🍽️ Du bist Gast. Bedanke dich und lobe das Essen.", "rollenB": "🏡 Du bist Gastgeber. Biete mehr Essen an und frag, wie es schmeckt.", "hilfe": ["Guten Appetit!", "Das schmeckt sehr lecker!", "Möchtest du noch etwas?", "Nein danke, ich bin satt."], "pts": 15}, "quiz": [{"q": "Was sagt man vor dem Essen?", "o": ["„Guten Appetit!“", "„Gute Nacht!“", "„Gute Besserung!“"], "r": 0}, {"q": "Was ist Abendbrot?", "o": ["kaltes Abendessen mit Brot", "ein warmes Frühstück", "ein Kuchen"], "r": 0}, {"q": "Wann gibt es oft Kaffee und Kuchen?", "o": ["am Nachmittag", "um Mitternacht", "vor dem Frühstück"], "r": 0}]});

